    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress fraction
    let progress = step_index as f64 / total_items as f64;

    // Residual after placement (already given)
    let residual_after = post_residual as f64;

    // Base weighted residual
    let mut score = residual_after * 0.80;

    // Residual ratio penalty (encourages tighter fits)
    let ratio = residual_after / bin_capacity as f64;
    score += ratio * ratio * 0.07;

    // Early‑stage tightening vs late‑stage loosening
    let early = (1.0 - progress).powf(2.0);
    let late = progress.powf(1.4);
    score += early * ratio * 0.25 + late * ratio * 0.05;

    // Open‑bin congestion penalty (logarithmic)
    let open_log = ((open_bins_count + 1) as f64).ln();
    score += open_log * residual_after * 0.015;

    // Mean‑residual deviation penalty
    let mean_diff = (residual_after - mean_residual).abs();
    score -= mean_diff * 0.15;

    // Fitting‑bins penalty (fewer alternatives are better)
    let fitting_penalty = ((fitting_bins_count as f64 - 1.0).max(0.0)) * 1.20;
    score += fitting_penalty;

    // New‑bin bias: discourage opening when many bins already exist
    if bin_residual == bin_capacity {
        let new_bin_bias = if open_bins_count == 0 {
            0.0
        } else {
            ((open_bins_count as f64).ln().max(0.1)) * 0.60
        };
        score += new_bin_bias;
    }

    // Look‑ahead: penalize large next items that won't fit into the residual
    if next_item_size > residual_after as u32 {
        let diff = (next_item_size - residual_after as u32) as f64;
        let damp = (1.0 - progress).powi(2);
        score += diff * 1.8 * damp;
    }
    // Secondary look‑ahead for moderately large next items
    if next_item_size > bin_capacity / 3 && next_item_size > residual_after as u32 {
        let diff = (next_item_size as f64 - residual_after);
        let damp = (1.0 - progress).powf(1.4);
        score += diff * 1.2 * damp;
    }

    // Medium‑size item bonus: prefer bins that match the medium ratio
    if item_size > bin_capacity / 4 && item_size < bin_capacity * 3 / 4 {
        if (residual_after - mean_residual).abs() < 1.0 {
            let mid_bonus = (bin_residual as f64 / bin_capacity as f64) * 0.02;
            score -= mid_bonus + 0.4;
        }
    }

    // Tight‑fit bonus for very small residuals when overall waste is large
    if bin_residual < bin_capacity / 20 && residual_after > mean_residual {
        score -= 1.5;
    }

    // Reward almost‑empty bins when waste is already low
    if residual_after < 1.0 {
        score -= 1.0;
    } else if residual_after > 35.0 {
        score += 0.4;
    }

    // Residual ratio close to mean ratio bonus
