        ((o / (total_items as f64 + 1.0)).powi(2)) * r * 0.15;

    // Prefer residual close to the mean
    let mean_term = -((r - m).abs() * 0.1);

    // Penalise bins that are not the last fitting option
    let fitting_penalty = (f - 1.0).max(0.0) * 5.0;

    // New‑bin penalty (if there are already open bins)
